from flask import Flask, render_template, request, redirect, url_for
import os

app = Flask(__name__)

@app.route('/create_folder', methods=['POST'])
def create_folder():
   path = request.form['path']

   os.makedirs(path, exist_ok=True)

   return 'Folder created!'

if __name__ == '__main__':
   app.run()

